// === Tab: mySketch ===
let myShader; 
var pos=[[-1.5, 0,-5],[-1, 0,0],[1, 1,-2]];
var vel=[[2, 0,0],[-1, 0,0],[5,0,0]];
var rad=[2.5,0.5,0.25];

function preload(){
  myShader = loadShader('https://openprocessing.org/sketch/1672473/files/basic.vert', 'basic.frag');
}

function setup() {
  createCanvas(1112, 834, WEBGL);
  noStroke();
}

function draw() {
  myShader.setUniform('resolution', [width, height]);
  myShader.setUniform('largePos', pos[0]);
  myShader.setUniform('midPos', pos[1]);
  myShader.setUniform('smallPos', pos[2]);
  myShader.setUniform('lr', rad[0]);
  myShader.setUniform('mr', rad[1]);
  myShader.setUniform('sr', rad[2]);

  myShader.setUniform('time', frameCount * 0.01);

  shader(myShader);
  handShake(pos);
  rect(0,0,width, height);
}

function handShake(array){
  for(var i=0;i<array.length;i++){
    pos[i][0]+=vel[i][0]*0.001;
    pos[i][1]+=vel[i][1]*0.001;
    pos[i][2]+=vel[i][2]*0.001;
    for(var j=0;j<array.length-i;j++){
      vel[i][0]-=pos[i][0]-pos[j][0];
      vel[j][0]-=pos[j][0]-pos[i][0];
      vel[i][1]-=pos[i][1]-pos[j][1];
      vel[j][1]-=pos[j][1]-pos[i][1];
      //pos[i][0]=lerp(pos[i][0],pos[j][0],0.1);
    }
  }

}

function windowResized(){
  resizeCanvas(width, height);
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  } 
}

